/**
 * @summary Get ESG summary metrics for an organisation
 */
export const getGetOrganisationSummaryUrl = (
  orgId: string,
  params?: GetOrganisationSummaryParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/organisations/${orgId}/summary?${stringifiedParams}`
    : `/api/organisations/${orgId}/summary`;
};

